script:
(function () {
  'use strict';
  // Earned income credit (IRC 32) for tax year 2026.
  //   credit = min(credit rate x earned income, max credit - phase-out rate x (larger of AGI or
  //            earned income - phase-out threshold)), never below 0  (IRC 32(a)(2)).
  //   Earned income = wages + elected nontaxable combat pay + self-employment profit - half of
  //     self-employment tax (Pub. 596 Worksheet B). AGI = wages + SE profit - half SE tax +
  //     investment income + other income - adjustments.
  //   Not allowed if investment income is over the limit, if someone else can claim you, without
  //     an SSN valid for work, or (married filing separately) unless the separated-spouse rules are
  //     met with a qualifying child. With no qualifying child: age 25-64 and a US main home for
  //     more than half the year.
  // Verified (Node, scratch tests):
  //   Max credits reproduce from the rates: 34% x $13,020 = $4,427; 40% x $18,290 = $7,316;
  //     45% x $18,290 = $8,231; 7.65% x $8,680 = $664.
  //   Completed phase-out amounts match Rev. Proc. 2025-32 (rounded to the dollar) for all 8 cases (e.g.
  //     $31,160 + $4,427 / 15.98% = $58,863 joint, 1 child; $10,860 + $664 / 7.65% = $19,540 single, none).
  //   HOH $25,000 wages, 1 child -> $4,427 - 15.98% x $1,110 = $4,249.62 (same as income-tax-calculator).
  //   Single $6,000 wages, no child -> 7.65% x $6,000 = $459.00. MFJ $40,000, 2 children ->
  //     $7,316 - 21.06% x $8,840 = $5,454.30. Single, 1 child, $5,000 wages + $35,000 other income
  //     (AGI $40,000) -> min(34% x $5,000 = $1,700, $4,427 - 15.98% x $16,110 = $1,852.62)
  //     = $1,700.00. Investment income $12,201 -> not eligible, $0.
  //   IRS EIC tables use $50 income bands, so a return can differ from this by a few dollars.
  //
  // ---- 2026 EARNED INCOME CREDIT CONSTANTS (tax year 2026) ---------------------------------
  // Earned income amounts, maximum credits, phase-out thresholds and the $12,200 investment income
  //   limit: IRS Rev. Proc. 2025-32, section 4.06. Credit and phase-out percentages are statutory
  //   (IRC 32(b)(1)). Age 25-64 rule for workers without a qualifying child: IRC 32(c)(1)(A)(ii).
  // Social Security wage base $184,500 and SE tax 15.3% on 92.35% of profit (for the half-SE-tax
  //   adjustment): SSA / IRC 1401, 1402.
  var TAX_YEAR = 2026;
  var EIC = { // index = qualifying children 0, 1, 2, 3+
    rate:       [0.0765, 0.34, 0.40, 0.45],
    earnedAmt:  [8680, 13020, 18290, 18290],
    maxCredit:  [664, 4427, 7316, 8231],
    phaseRate:  [0.0765, 0.1598, 0.2106, 0.2106],
    start:      [10860, 23890, 23890, 23890],   // all filing statuses other than joint
    startJoint: [18140, 31160, 31160, 31160]    // married filing jointly
  };
  var INVESTMENT_LIMIT = 12200;
  var SS_WAGE_BASE = 184500, SE_FACTOR = 0.9235, SE_SS = 0.124, SE_MED = 0.029;
  // -------------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function raw(id) { return el(id).value.trim() === '' ? 0 : parseFloat(el(id).value); }

  function creditFor(n, earned, agi, joint) {
    if (earned <= 0) return 0;
    var start = joint ? EIC.startJoint[n] : EIC.start[n];
    var phaseIn = Math.min(EIC.rate[n] * earned, EIC.maxCredit[n]);
    var cap = EIC.maxCredit[n] - EIC.phaseRate[n] * Math.max(0, Math.max(agi, earned) - start);
    return Math.max(0, Math.min(phaseIn, cap));
  }
  function endOfPhaseOut(n, joint) {
    var start = joint ? EIC.startJoint[n] : EIC.start[n];
    return start + EIC.maxCredit[n] / EIC.phaseRate[n];
  }

  function compute(o) {
    var joint = o.status === 'mfj', n = Math.min(3, Math.max(0, o.kids));
    var nese = o.selfEmp * SE_FACTOR;
    var seTax = nese >= 400 ? SE_SS * Math.min(nese, Math.max(0, SS_WAGE_BASE - o.wages)) + SE_MED * nese : 0;
    var earned = o.wages + o.combat + o.selfEmp - seTax / 2;
    var agi = o.wages + o.selfEmp - seTax / 2 + o.invest + o.other - o.adjust;
    var reasons = [];
    if (o.status === 'mfs' && (!o.separated || n === 0))
      reasons.push('Married filing separately qualifies only if you meet the separated-spouse rules and have a qualifying child.');
    if (!o.ssn) reasons.push('Everyone counted for the credit needs a Social Security number valid for employment.');
    if (o.dependent) reasons.push('You cannot claim the credit if someone else can claim you as a dependent or qualifying child.');
    if (n === 0 && !o.age) reasons.push('Without a qualifying child, you (or your spouse) must be at least 25 and under 65 at the end of the year.');
    if (n === 0 && !o.usHome) reasons.push('Without a qualifying child, your main home must be in the United States for more than half the year.');
    if (o.invest > INVESTMENT_LIMIT) reasons.push('Investment income is over the ' + whole.format(INVESTMENT_LIMIT) + ' limit for ' + TAX_YEAR + '.');
    if (earned <= 0) reasons.push('You need earned income (wages or self-employment profit) to qualify.');
    var credit = reasons.length ? 0 : creditFor(n, earned, agi, joint);
    var start = joint ? EIC.startJoint[n] : EIC.start[n], test = Math.max(agi, earned), stage;
    if (reasons.length) stage = 'Not eligible';
    else if (credit <= 0) stage = 'Income above the credit range';
    else if (test > start) stage = 'Phase-out: the credit shrinks as income rises';
    else if (earned < EIC.earnedAmt[n]) stage = 'Phase-in: the credit grows with each dollar earned';
    else stage = 'Plateau: you get the maximum credit';
    return { n: n, joint: joint, earned: earned, agi: agi, seTax: seTax, credit: credit, reasons: reasons,
             stage: stage, start: start, end: endOfPhaseOut(n, joint) };
  }

  function cell(text) { var td = document.createElement('td'); td.textContent = text; return td; }

  function update() {
    var o = {
      status: el('eiStatus').value, kids: parseInt(el('eiKids').value, 10) || 0,
      wages: raw('eiWages'), selfEmp: raw('eiSelfEmp'), invest: raw('eiInvest'),
      other: raw('eiOther'), adjust: raw('eiAdjust'), combat: raw('eiCombat'),
      separated: el('eiSeparated').checked, ssn: el('eiSsn').checked, dependent: el('eiDependent').checked,
      age: el('eiAge').checked, usHome: el('eiUsHome').checked
    };
    el('eiSeparatedWrap').hidden = o.status !== 'mfs';
    var error = el('eiError');
    var vals = [o.wages, o.selfEmp, o.invest, o.other, o.adjust, o.combat];
    var bad = vals.some(function (v) { return isNaN(v) || !isFinite(v) || v < 0 || v > 1e9; });
    error.hidden = !bad;
    if (bad) { error.textContent = 'Enter amounts of $0 or more (leave a box at 0 if it does not apply).'; return; }

    var r = compute(o);
    el('eiCredit').textContent = money.format(r.credit);
    el('eiMax').textContent = whole.format(EIC.maxCredit[r.n]);
    el('eiStage').textContent = r.stage;
    el('eiEarned').textContent = money.format(r.earned);
    el('eiAgi').textContent = money.format(r.agi);
    el('eiRange').textContent = whole.format(r.start) + ' to ' + whole.format(Math.round(r.end));
    el('eiSeTaxRow').hidden = r.seTax <= 0;
    el('eiSeTax').textContent = money.format(r.seTax / 2);
    var note = el('eiNote');
    note.hidden = r.reasons.length === 0;
    note.textContent = r.reasons.join(' ');

    var body = el('eiTable');
    while (body.firstChild) body.removeChild(body.firstChild);
    var labels = ['None', 'One', 'Two', 'Three or more'];
    for (var k = 0; k < 4; k++) {
      var tr = document.createElement('tr');
      var st = r.joint ? EIC.startJoint[k] : EIC.start[k];
      tr.appendChild(cell(labels[k]));
      tr.appendChild(cell(whole.format(EIC.maxCredit[k])));
      tr.appendChild(cell(whole.format(EIC.earnedAmt[k])));
      tr.appendChild(cell(whole.format(st)));
      tr.appendChild(cell(whole.format(Math.round(endOfPhaseOut(k, r.joint)))));
      tr.appendChild(cell(money.format(creditFor(k, r.earned, r.agi, r.joint))));
      if (k === r.n) tr.className = 'font-semibold';
      body.appendChild(tr);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('eiForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
